BEGIN;SET LOCAL statement_timeout='8s';SET LOCAL lock_timeout='1s';SELECT pg_advisory_xact_lock(2026083000261022);
DO $admit$ DECLARE c population_top3000_202608_202609_v1.acquisition_control%rowtype;p population_top3000_202608_202609_v1.pipeline_control%rowtype;v_rel bigint;t population_top3000_202608_202609_v1.pipeline_task%rowtype;BEGIN
 SELECT * INTO c FROM population_top3000_202608_202609_v1.acquisition_control WHERE singleton FOR UPDATE;
 SELECT * INTO p FROM population_top3000_202608_202609_v1.pipeline_control WHERE singleton FOR UPDATE;
 IF c.owner_id<>'top3000-recovery-20261023-root-4b1314bcb5c2' OR c.owner_fence<>2 OR c.stop_generation<>0 OR c.owner_id IS DISTINCT FROM p.expected_owner_id OR c.owner_fence IS DISTINCT FROM p.expected_owner_fence OR c.stop_generation IS DISTINCT FROM p.expected_stop_generation OR c.scope_sha256 IS DISTINCT FROM p.scope_sha256 OR c.scope_sha256<>'8e6ca1178f03822c34bb1b339818b34dcfdbf2a8642ef875e6e1af34dbf1bedd' OR NOT c.enabled OR c.stopped OR c.hold_reason IS NOT NULL OR NOT p.enabled OR c.admitted_until<=clock_timestamp() OR p.deadline<=clock_timestamp() OR p.budget_cap_usd<>250 OR p.unavoidable_usd<>76.03 OR p.repair_egress_reserve_usd<>50 OR p.remaining_uncommitted_usd<>123.97 OR c.max_provider_requests<>5899 OR c.max_http_invocations<>5957 THEN RAISE EXCEPTION 'CURRENT_OWNER_AND_EXISTING_BUDGET_REVISION_REQUIRED';END IF;
 SELECT coalesce(sum(pg_total_relation_size(r.oid)),0) INTO v_rel FROM pg_class r JOIN pg_namespace n ON n.oid=r.relnamespace WHERE n.nspname='population_top3000_202608_202609_v1' AND r.relkind IN('r','m');
 IF v_rel>=2000000000 OR c.stored_bytes+c.reserved_bytes>=250000000 THEN RAISE EXCEPTION 'STORAGE_REVIEW_REQUIRED_BEFORE_REQUEST_EXTENSION';END IF;
 UPDATE population_top3000_202608_202609_v1.acquisition_control SET max_provider_requests=c.provider_requests+200,max_http_invocations=c.http_invocations+200,updated_at=clock_timestamp() WHERE singleton;
 UPDATE population_top3000_202608_202609_v1.pipeline_control SET budget_verified_at=clock_timestamp(),budget_evidence=jsonb_set(jsonb_set(budget_evidence,'{resource_limits,provider_request_ceiling}',to_jsonb(c.provider_requests+200)),'{resource_limits,http_invocation_ceiling}',to_jsonb(c.http_invocations+200))||
 jsonb_build_object('continuation_request_envelope',jsonb_build_object('reviewed_at',clock_timestamp(),'provider_baseline',c.provider_requests,'http_baseline',c.http_invocations,'maximum_future_provider_calls',200,'maximum_future_http_invocations',200,'conservative_cost_within_existing_infrastructure_usd',5.80,'edge_package_boundary_allowance_usd',4.00,'traffic_allowance_usd',1.80,'traffic_allowance_gb',20,'changes_money_fields',false,'changes_storage_caps',false,'new_subscription_or_capacity',false,'invoice_reconciled',false,'pricing_sources',jsonb_build_array('https://supabase.com/docs/guides/platform/manage-your-usage/edge-function-invocations','https://supabase.com/docs/guides/platform/manage-your-usage/egress')),
 'allowed_work',budget_evidence->'allowed_work'||jsonb_build_array('Reviewed continuation of existing Massive short-interest fixed-settlement archive through up to128 pages; fixed dates and sourcecursor preserved; no additionalsubscription','Planned42-session Massive grouped-daily compact source;41remainingproviderdays and retainedAug3reuse; separate actualreview/test/registration required','Up to20 targeted company-reference source calls after exactcase/source admission; no massSECqueueadmission')) WHERE singleton;
 SELECT * INTO t FROM population_top3000_202608_202609_v1.pipeline_task WHERE task_id='d4a27e18-ff2f-49e9-86c3-7200f2ee8814' FOR UPDATE;
 IF t.status NOT IN('READY','BLOCKED','LEASED') OR t.payload->>'max_pages'<>'48' OR t.input_versions->>'shortinterest_bundle_sha256'<>'18f46852bf04cd495613e333c2fcedc9df66c9e3e3c68600070d3d77314ad15b' THEN RAISE EXCEPTION 'S02_CONTINUATION_STATE_CHANGED';END IF;
 UPDATE population_top3000_202608_202609_v1.pipeline_task SET payload=jsonb_set(payload,'{max_pages}','128') WHERE task_id=t.task_id;
 INSERT INTO population_top3000_202608_202609_v1.pipeline_event(event,details) VALUES('BOUNDED_PREPAID_CONTINUATION_REQUEST_ENVELOPE_ADMITTED',jsonb_build_object('owner_fence',2,'stop_generation',0,'prior_provider_ceiling',c.max_provider_requests,'prior_http_ceiling',c.max_http_invocations,'provider_baseline',c.provider_requests,'http_baseline',c.http_invocations,'provider_ceiling',c.provider_requests+200,'http_ceiling',c.http_invocations+200,'current_raw_bytes',c.stored_bytes,'current_relation_bytes',v_rel,'raw_cap',250000000,'relation_cap',2000000000,'money_fields_unchanged',true,'budget_cap_usd',250,'existing_infrastructure_encumbrance_usd',10,'reviewed_operation_envelope_usd',5.80,'no_new_purchase_or_capacity',true,'invoice_reconciled',false,'S02_max_pages',128,'S02_current_checkpoint_preserved',t.checkpoint));
END $admit$;
SELECT jsonb_build_object('provider_ceiling',max_provider_requests,'http_ceiling',max_http_invocations,'current_provider',provider_requests,'current_http',http_invocations,'source_bytes',stored_bytes) result FROM population_top3000_202608_202609_v1.acquisition_control WHERE singleton;COMMIT;